import streamlit as st

st.set_page_config(page_title="Online Store", layout="wide")
st.title("🛍️ Simple Online Store (Real Product Images)")

# --- 商品清單：真實商品照片 ---
if "products" not in st.session_state:
    st.session_state.products = {
        # 🥦 Food & Drinks
        "Apple": {"price": 30, "image": "https://images.unsplash.com/photo-1567306226416-28f0efdc88ce"},
        "Banana": {"price": 20, "image": "data:image/jpeg;base64,"},
        "Instant Noodles": {"price": 45, "image": "data:image/jpeg;base64,"},
        "Mineral Water": {"price": 25, "image": "data:image/jpeg;base64,"},
        "Chocolate": {"price": 60, "image": "data:image/jpeg;base64,"},
        "Bread": {"price": 35, "image": "https://images.unsplash.com/photo-1608198093002-ad4e005484ec"},
        "Coffee": {"price": 55, "image": "https://images.unsplash.com/photo-1509042239860-f550ce710b93"},
        "Cookies": {"price": 40, "image": "data:image/jpeg;base64,"},
        "Milk": {"price": 50, "image": "data:image/jpeg;base64,"},
        # 🧴 Daily Essentials
        "Toothbrush": {"price": 25, "image": "data:image/jpeg;base64,"},
        "Toothpaste": {"price": 60, "image": "data:image/jpeg;base64,"},
        "Shampoo": {"price": 120, "image": "data:image/jpeg;base64,"},
        "Body Wash": {"price": 110, "image": "data:image/jpeg;base64,"},
        "Tissue": {"price": 45, "image": "data:image/jpeg;base64,"},
        "Laundry Detergent": {"price": 180, "image": "data:image/jpeg;base64,"},
        "Trash Bag": {"price": 50, "image": "data:image/jpeg;base64,"},
        "Hand Sanitizer": {"price": 75, "image": "data:image/jpeg;base64,"},
        "Soap Bar": {"price": 90, "image": "data:image/jpeg;base64,"},
       
        # 🎁 Stationery & Small Gifts
        "Pen": {"price": 25, "image": "data:image/jpeg;base64,"},
        "Notebook": {"price": 60, "image": "data:image/jpeg;base64,"},
        "Night Light": {"price": 180, "image": "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQYMJK4xlaRsDj1Dj1I2ukGLH3SNgNe7mwENw&s"},
        "Coin Purse": {"price": 90, "image": "data:image/jpeg;base64,"},
        "Keychain": {"price": 70, "image": "data:image/jpeg;base64,"},
        "Water Bottle": {"price": 150, "image": "data:image/jpeg;base64,"},
        "Bookmark": {"price": 20, "image": "data:image/jpeg;base64,"},
        "Tape": {"price": 30, "image": "data:image/jpeg;base64,"},
        "Sticker Pack": {"price": 40, "image": "data:image/jpeg;base64,"}
    }

# 初始化購物車
if "cart" not in st.session_state:
    st.session_state.cart = {}

# --- 顯示商品 ---
st.header("🛒 Product List")
product_names = list(st.session_state.products.keys())

for i in range(0, len(product_names), 3):
    cols = st.columns(3)
    for j, name in enumerate(product_names[i:i+3]):
        with cols[j]:
            product = st.session_state.products[name]
            st.image(product["image"], width=220, caption=name)
            
            st.write(f"💰 **{product['price']} NT$**")
            qty = st.number_input("Quantity", min_value=0, value=0, key=f"{name}_qty")
            if st.button("Add to Cart", key=f"add_{name}"):
                if qty > 0:
                    st.session_state.cart[name] = st.session_state.cart.get(name, 0) + qty
                    st.success(f"Added {qty} x {name} to cart")

# --- 購物車 ---
st.header("🧺 Shopping Cart")
if st.session_state.cart:
    total = 0
    for item, qty in st.session_state.cart.items():
        price = st.session_state.products[item]["price"] * qty
        col1, col2 = st.columns([1,5])
        with col1:
            st.image(st.session_state.products[item]["image"], width=50)
        with col2:
            st.write(f"{item} × {qty} = {price} NT$")
        total += price
    
    st.write(f"**Total: {total} NT$**")
    
    col_clear, col_checkout = st.columns(2)
    with col_clear:
        if st.button("Clear Cart"):
            st.session_state.cart = {}
            st.success("Cart cleared!")
    with col_checkout:
        if st.button("Checkout"):
            st.success(f"Checked out {len(st.session_state.cart)} items! Total: {total} NT$")
            st.session_state.cart = {}
else:
    st.write("Your cart is empty.")
